"use client"

import { useRef, useEffect, useState, useCallback } from "react"
import { postEvent } from "../api"

const WebcamMonitor = ({ sessionId, onFocusChange, isActive }) => {
  const videoRef = useRef(null)
  const canvasRef = useRef(null)
  const streamRef = useRef(null)
  const intervalRef = useRef(null)
  const previousFrameRef = useRef(null)
  const faceDetectorRef = useRef(null)

  const [isWebcamActive, setIsWebcamActive] = useState(false)
  const [error, setError] = useState(null)
  const [presenceStatus, setPresenceStatus] = useState("present")
  const [confidence, setConfidence] = useState(0)
  const [faceDetectionReady, setFaceDetectionReady] = useState(false)
  const [detectionMethod, setDetectionMethod] = useState("basic") // "basic" or "advanced"
  const [facePosition, setFacePosition] = useState({ x: 0, y: 0, width: 0, height: 0 })
  const [headPose, setHeadPose] = useState({ yaw: 0, pitch: 0, roll: 0 })
  const [eyeGaze, setEyeGaze] = useState({ direction: "center", confidence: 0 })

  // Initialize advanced face detection
  const initializeFaceDetection = useCallback(async () => {
    try {
      // Check if MediaPipe Face Detection is available
      if ("FaceDetector" in window) {
        const faceDetector = new window.FaceDetector({
          maxDetectedFaces: 1,
          fastMode: false,
        })
        faceDetectorRef.current = faceDetector
        setFaceDetectionReady(true)
        setDetectionMethod("advanced")
        console.log("Advanced face detection initialized")
      } else {
        // Fallback to basic detection
        console.log("MediaPipe not available, using basic detection")
        setDetectionMethod("basic")
        setFaceDetectionReady(true)
      }
    } catch (error) {
      console.error("Face detection initialization failed:", error)
      setDetectionMethod("basic")
      setFaceDetectionReady(true)
    }
  }, [])

  // Webcam initialization
  const initializeWebcam = useCallback(async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: {
          width: 640,
          height: 480,
          facingMode: "user",
          frameRate: { ideal: 30, max: 30 },
        },
      })

      streamRef.current = stream
      if (videoRef.current) {
        videoRef.current.srcObject = stream
        setIsWebcamActive(true)
        setError(null)

        // Initialize face detection after webcam is ready
        videoRef.current.onloadedmetadata = () => {
          initializeFaceDetection()
        }
      }
    } catch (err) {
      console.error("Webcam access error:", err)
      setError("Unable to access webcam. Please check permissions.")
      setIsWebcamActive(false)
    }
  }, [initializeFaceDetection])

  // Stop webcam
  const stopWebcam = useCallback(() => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((track) => track.stop())
      streamRef.current = null
    }
    setIsWebcamActive(false)
    setFaceDetectionReady(false)
  }, [])

  // Advanced face detection with head pose estimation
  const detectFaceAndPose = useCallback(async () => {
    if (!videoRef.current || !canvasRef.current || !isWebcamActive) return null

    const video = videoRef.current
    const canvas = canvasRef.current
    const ctx = canvas.getContext("2d")

    canvas.width = video.videoWidth
    canvas.height = video.videoHeight
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height)

    try {
      if (detectionMethod === "advanced" && faceDetectorRef.current) {
        // Use MediaPipe Face Detection
        const faces = await faceDetectorRef.current.detect(video)

        if (faces && faces.length > 0) {
          const face = faces[0]
          const boundingBox = face.boundingBox

          // Update face position
          setFacePosition({
            x: boundingBox.x,
            y: boundingBox.y,
            width: boundingBox.width,
            height: boundingBox.height,
          })

          // Estimate head pose based on face landmarks
          const headPoseData = estimateHeadPose(face, canvas.width, canvas.height)
          setHeadPose(headPoseData)

          // Estimate eye gaze direction
          const gazeData = estimateEyeGaze(face, headPoseData)
          setEyeGaze(gazeData)

          return {
            faceDetected: true,
            confidence: face.confidence || 0.8,
            headPose: headPoseData,
            eyeGaze: gazeData,
            facePosition: boundingBox,
          }
        }
      } else {
        // Fallback to basic detection
        return await basicFaceDetection(ctx, canvas.width, canvas.height)
      }
    } catch (error) {
      console.error("Face detection error:", error)
      return await basicFaceDetection(ctx, canvas.width, canvas.height)
    }

    return { faceDetected: false, confidence: 0 }
  }, [detectionMethod, isWebcamActive])

  // Basic face detection using color and movement analysis
  const basicFaceDetection = useCallback(async (ctx, width, height) => {
    const imageData = ctx.getImageData(0, 0, width, height)
    const data = imageData.data

    // Detect skin-colored regions (simplified)
    let skinPixels = 0
    const totalPixels = data.length / 4
    let centerX = 0,
      centerY = 0,
      facePixelCount = 0

    for (let i = 0; i < data.length; i += 4) {
      const r = data[i]
      const g = data[i + 1]
      const b = data[i + 2]

      // Simple skin color detection
      if (isSkinColor(r, g, b)) {
        skinPixels++
        const pixelIndex = i / 4
        const x = pixelIndex % width
        const y = Math.floor(pixelIndex / width)

        // Focus on upper half for face detection
        if (y < height * 0.6) {
          centerX += x
          centerY += y
          facePixelCount++
        }
      }
    }

    if (facePixelCount > 1000) {
      // Minimum pixels for face detection
      centerX /= facePixelCount
      centerY /= facePixelCount

      // Estimate head pose based on face center position
      const headPoseData = estimateBasicHeadPose(centerX, centerY, width, height)
      setHeadPose(headPoseData)

      const gazeData = {
        direction: getGazeDirection(headPoseData.yaw),
        confidence: Math.min((skinPixels / totalPixels) * 10, 1),
      }
      setEyeGaze(gazeData)

      return {
        faceDetected: true,
        confidence: Math.min((skinPixels / totalPixels) * 5, 1),
        headPose: headPoseData,
        eyeGaze: gazeData,
        facePosition: { x: centerX - 50, y: centerY - 50, width: 100, height: 100 },
      }
    }

    return { faceDetected: false, confidence: 0 }
  }, [])

  // Helper function to detect skin color
  const isSkinColor = (r, g, b) => {
    // Simplified skin color detection
    return (
      r > 95 && g > 40 && b > 20 && Math.max(r, g, b) - Math.min(r, g, b) > 15 && Math.abs(r - g) > 15 && r > g && r > b
    )
  }

  // Estimate head pose from face landmarks or position
  const estimateHeadPose = (face, canvasWidth, canvasHeight) => {
    if (face.landmarks) {
      // Use landmarks for more accurate pose estimation
      const landmarks = face.landmarks
      // This would require more complex 3D pose estimation
      // For now, use simplified estimation based on face center
      const centerX = face.boundingBox.x + face.boundingBox.width / 2
      const centerY = face.boundingBox.y + face.boundingBox.height / 2

      return estimateBasicHeadPose(centerX, centerY, canvasWidth, canvasHeight)
    }

    const centerX = face.boundingBox.x + face.boundingBox.width / 2
    const centerY = face.boundingBox.y + face.boundingBox.height / 2

    return estimateBasicHeadPose(centerX, centerY, canvasWidth, canvasHeight)
  }

  // Basic head pose estimation based on face position
  const estimateBasicHeadPose = (centerX, centerY, canvasWidth, canvasHeight) => {
    const centerXNorm = (centerX - canvasWidth / 2) / (canvasWidth / 2)
    const centerYNorm = (centerY - canvasHeight / 2) / (canvasHeight / 2)

    // Convert to approximate angles (in degrees)
    const yaw = centerXNorm * 45 // Left/Right rotation
    const pitch = -centerYNorm * 30 // Up/Down rotation
    const roll = 0 // Simplified, no roll detection

    return { yaw, pitch, roll }
  }

  // Estimate eye gaze direction
  const estimateEyeGaze = (face, headPose) => {
    const yaw = headPose.yaw
    let direction = "center"
    let confidence = 0.7

    if (Math.abs(yaw) > 25) {
      direction = yaw > 0 ? "right" : "left"
      confidence = Math.min(Math.abs(yaw) / 45, 1)
    } else if (Math.abs(yaw) > 15) {
      direction = yaw > 0 ? "slight-right" : "slight-left"
      confidence = Math.abs(yaw) / 25
    }

    return { direction, confidence }
  }

  // Get gaze direction from yaw angle
  const getGazeDirection = (yaw) => {
    if (Math.abs(yaw) > 25) {
      return yaw > 0 ? "right" : "left"
    } else if (Math.abs(yaw) > 15) {
      return yaw > 0 ? "slight-right" : "slight-left"
    }
    return "center"
  }

  // Enhanced presence detection with face analysis
  const detectPresence = useCallback(async () => {
    if (!videoRef.current || !canvasRef.current || !isWebcamActive) return

    const video = videoRef.current
    const canvas = canvasRef.current
    const ctx = canvas.getContext("2d")

    canvas.width = video.videoWidth
    canvas.height = video.videoHeight
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height)

    // Get face detection results
    const faceData = await detectFaceAndPose()

    let isPresent = false
    let confidenceScore = 0

    if (faceData && faceData.faceDetected) {
      // Advanced presence detection based on face and gaze
      const { headPose, eyeGaze, confidence: faceConfidence } = faceData

      // Check if user is looking at the screen
      const isLookingAtScreen =
        eyeGaze.direction === "center" || eyeGaze.direction === "slight-left" || eyeGaze.direction === "slight-right"

      // Check head pose - not turned too far away
      const headPoseOk = Math.abs(headPose.yaw) < 35 && Math.abs(headPose.pitch) < 25

      isPresent = isLookingAtScreen && headPoseOk && faceConfidence > 0.3
      confidenceScore = Math.round(faceConfidence * eyeGaze.confidence * 100)

      // Additional movement analysis for better accuracy
      if (previousFrameRef.current) {
        const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height)
        const { movement, brightness } = analyzeFrame(imageData.data, previousFrameRef.current)

        // Combine face detection with movement analysis
        const movementOk = movement > 2 && movement < 40
        const lightingOk = brightness > 30 && brightness < 200

        if (!movementOk || !lightingOk) {
          confidenceScore *= 0.7 // Reduce confidence if movement/lighting is poor
        }

        previousFrameRef.current = new Uint8ClampedArray(imageData.data)
      } else {
        const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height)
        previousFrameRef.current = new Uint8ClampedArray(imageData.data)
      }
    } else {
      // Fallback to basic detection if face detection fails
      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height)
      const currentFrame = imageData.data

      if (previousFrameRef.current) {
        const { movement, brightness } = analyzeFrame(currentFrame, previousFrameRef.current)
        isPresent = detectPresenceHeuristic(movement, brightness)
        confidenceScore = calculateConfidence(movement, brightness)
      }

      previousFrameRef.current = new Uint8ClampedArray(currentFrame)
    }

    setConfidence(confidenceScore)

    const newStatus = isPresent ? "present" : "distracted"
    if (newStatus !== presenceStatus) {
      setPresenceStatus(newStatus)
      onFocusChange(newStatus)

      // Send detailed event to backend
      if (sessionId) {
        postEvent(sessionId, newStatus, {
          confidence: confidenceScore,
          detectionMethod,
          faceDetected: faceData?.faceDetected || false,
          headPose: headPose,
          eyeGaze: eyeGaze.direction,
          gazeConfidence: eyeGaze.confidence,
          timestamp: new Date().toISOString(),
        }).catch(console.error)
      }
    }
  }, [sessionId, onFocusChange, presenceStatus, isWebcamActive, detectionMethod, headPose, eyeGaze])

  // Frame analysis helper functions (keeping existing ones)
  const analyzeFrame = (currentFrame, previousFrame) => {
    let totalDifference = 0
    let totalBrightness = 0
    const pixelCount = currentFrame.length / 4

    for (let i = 0; i < currentFrame.length; i += 4) {
      const currentBrightness = (currentFrame[i] + currentFrame[i + 1] + currentFrame[i + 2]) / 3
      const previousBrightness = (previousFrame[i] + previousFrame[i + 1] + previousFrame[i + 2]) / 3

      totalBrightness += currentBrightness
      totalDifference += Math.abs(currentBrightness - previousBrightness)
    }

    return {
      movement: totalDifference / pixelCount,
      brightness: totalBrightness / pixelCount,
    }
  }

  const detectPresenceHeuristic = (movement, brightness) => {
    const MOVEMENT_THRESHOLD = 5
    const BRIGHTNESS_MIN = 30
    const BRIGHTNESS_MAX = 200

    const hasMovement = movement > MOVEMENT_THRESHOLD && movement < 50
    const goodLighting = brightness > BRIGHTNESS_MIN && brightness < BRIGHTNESS_MAX

    return hasMovement && goodLighting
  }

  const calculateConfidence = (movement, brightness) => {
    let score = 50

    if (movement > 5 && movement < 20) {
      score += 30
    } else if (movement > 20) {
      score -= 20
    }

    if (brightness > 50 && brightness < 150) {
      score += 20
    }

    return Math.max(0, Math.min(100, score))
  }

  // Start monitoring when session is active
  useEffect(() => {
    if (isActive && isWebcamActive && faceDetectionReady) {
      intervalRef.current = setInterval(detectPresence, 1000) // Check every second
    } else {
      if (intervalRef.current) {
        clearInterval(intervalRef.current)
        intervalRef.current = null
      }
    }

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current)
      }
    }
  }, [isActive, isWebcamActive, faceDetectionReady, detectPresence])

  // Initialize webcam when component mounts
  useEffect(() => {
    if (isActive) {
      initializeWebcam()
    }

    return () => {
      stopWebcam()
      if (intervalRef.current) {
        clearInterval(intervalRef.current)
      }
    }
  }, [isActive, initializeWebcam, stopWebcam])

  // Inline styles for enhanced visual feedback
  const getStatusColor = () => {
    switch (presenceStatus) {
      case "present":
        return "#06ffa5"
      case "distracted":
        return "#ff006e"
      default:
        return "#00d4ff"
    }
  }

  const getGazeColor = () => {
    switch (eyeGaze.direction) {
      case "center":
        return "#06ffa5"
      case "slight-left":
      case "slight-right":
        return "#fb8500"
      case "left":
      case "right":
        return "#ff006e"
      default:
        return "#00d4ff"
    }
  }

  return (
    <div className="webcam-monitor">
      <div className="monitor-header">
        <h3>Advanced Webcam Monitor</h3>
        <div
          className={`status-badge ${presenceStatus}`}
          style={{
            background: `linear-gradient(135deg, ${getStatusColor()}, ${getStatusColor()}88)`,
            border: `2px solid ${getStatusColor()}`,
            boxShadow: `0 0 20px ${getStatusColor()}44`,
          }}
        >
          {presenceStatus === "present" ? "👁️ Focused" : "😴 Distracted"}
        </div>
      </div>

      <div className="webcam-container">
        {error ? (
          <div className="webcam-error">
            <p>{error}</p>
            <button onClick={initializeWebcam} className="btn btn-secondary">
              Retry Webcam Access
            </button>
          </div>
        ) : (
          <>
            <video ref={videoRef} autoPlay muted playsInline className="webcam-video" />
            <canvas ref={canvasRef} style={{ display: "none" }} />

            {/* Face detection overlay */}
            {facePosition.width > 0 && (
              <div
                style={{
                  position: "absolute",
                  left: `${(facePosition.x / 640) * 100}%`,
                  top: `${(facePosition.y / 480) * 100}%`,
                  width: `${(facePosition.width / 640) * 100}%`,
                  height: `${(facePosition.height / 480) * 100}%`,
                  border: `2px solid ${getStatusColor()}`,
                  borderRadius: "8px",
                  boxShadow: `0 0 10px ${getStatusColor()}44`,
                  pointerEvents: "none",
                }}
              />
            )}
          </>
        )}
      </div>

      <div className="monitor-stats">
        <div className="stat">
          <label>Status:</label>
          <span className={presenceStatus} style={{ color: getStatusColor() }}>
            {presenceStatus}
          </span>
        </div>
        <div className="stat">
          <label>Confidence:</label>
          <span style={{ color: confidence > 70 ? "#06ffa5" : confidence > 40 ? "#fb8500" : "#ff006e" }}>
            {confidence}%
          </span>
        </div>
        <div className="stat">
          <label>Detection:</label>
          <span className={detectionMethod === "advanced" ? "active" : "inactive"}>
            {detectionMethod === "advanced" ? "Advanced" : "Basic"}
          </span>
        </div>
      </div>

      {/* Enhanced stats for face detection */}
      <div className="monitor-stats">
        <div className="stat">
          <label>Head Yaw:</label>
          <span style={{ color: Math.abs(headPose.yaw) > 25 ? "#ff006e" : "#06ffa5" }}>{headPose.yaw.toFixed(1)}°</span>
        </div>
        <div className="stat">
          <label>Head Pitch:</label>
          <span style={{ color: Math.abs(headPose.pitch) > 20 ? "#ff006e" : "#06ffa5" }}>
            {headPose.pitch.toFixed(1)}°
          </span>
        </div>
        <div className="stat">
          <label>Eye Gaze:</label>
          <span style={{ color: getGazeColor() }}>{eyeGaze.direction}</span>
        </div>
      </div>

      <div className="monitor-info">
        <h4>Advanced Detection Features:</h4>
        <ul>
          <li>✅ Real-time face detection and tracking</li>
          <li>✅ Head pose estimation (yaw, pitch, roll)</li>
          <li>✅ Eye gaze direction analysis</li>
          <li>✅ Distraction detection when looking away</li>
          <li>✅ Enhanced confidence scoring</li>
          <li>✅ Automatic fallback to basic detection</li>
        </ul>

        <div
          style={{
            marginTop: "1rem",
            padding: "1rem",
            background: "rgba(0, 212, 255, 0.1)",
            borderRadius: "8px",
            border: "1px solid rgba(0, 212, 255, 0.3)",
          }}
        >
          <h5 style={{ color: "#00d4ff", marginBottom: "0.5rem" }}>Detection Status:</h5>
          <p style={{ color: "rgba(255, 255, 255, 0.9)", fontSize: "0.9rem", margin: 0 }}>
            {detectionMethod === "advanced"
              ? "🎯 Using advanced face detection with head pose analysis"
              : "⚡ Using basic movement and color detection"}
          </p>
        </div>
      </div>
    </div>
  )
}

export default WebcamMonitor
